import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  createJob,
  getJob,
  listJobs,
  readHeartbeat,
  validateNewJob,
  type FieldError,
} from './jobs.ts';

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_STALE_MS = 3000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function sendMethodNotAllowed(res: ServerResponse, allow: string[]): void {
  send(
    res,
    405,
    { error: { code: 'method_not_allowed', message: `Method not allowed. Allowed: ${allow.join(', ')}.` } },
    { allow: allow.join(', ') },
  );
}

/** Reads the request body, or returns null when it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

/** Returns the media type of a Content-Type header, without parameters, lower-cased. */
function mediaType(header: string | undefined): string {
  return typeof header === 'string' ? header.split(';')[0]!.trim().toLowerCase() : '';
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const fields: FieldError[] = [];
  let body: unknown;

  if (raw === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (mediaType(req.headers['content-type']) !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    try {
      body = JSON.parse(raw);
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
  }

  const keyHeader = req.headers['idempotency-key'];
  let key: string | undefined;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY.test(keyHeader)) key = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  if (fields.length === 0) {
    const validated = validateNewJob(body);
    if (validated.ok) {
      const result = createJob(db, validated.value, key);
      if (result.kind === 'conflict') {
        sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        return;
      }
      send(res, result.kind === 'created' ? 201 : 200, result.job);
      return;
    }
    fields.push(...validated.fields);
  }

  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function handleGetJob(res: ServerResponse, id: string): void {
  const job = getJob(db, id);
  if (!job) sendError(res, 404, 'not_found', `No job with id ${id}.`);
  else send(res, 200, job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isRead = method === 'GET' || method === 'HEAD';

  if (pathname === '/') {
    if (!isRead) return sendMethodNotAllowed(res, ['GET', 'HEAD']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (!isRead) return sendMethodNotAllowed(res, ['GET', 'HEAD']);
    const beat = readHeartbeat(db, 'worker');
    const up = beat !== undefined && Date.now() - beat <= WORKER_STALE_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }

  if (pathname === '/api/jobs') {
    if (method === 'POST') return handleCreateJob(req, res);
    if (!isRead) return sendMethodNotAllowed(res, ['GET', 'HEAD', 'POST']);
    return send(res, 200, { jobs: listJobs(db) });
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (!isRead) return sendMethodNotAllowed(res, ['GET', 'HEAD']);
    return handleGetJob(res, decodeURIComponent(match[1]!));
  }

  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e instanceof Error ? e.message : e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.on('error', (e) => {
  console.error(`server failed to start on port ${port}: ${e.message}`);
  process.exit(1);
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2000).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

