import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';

/** Processing constants. */
export const STEP_MS = 100;
export const MAX_ATTEMPTS = 3;
export const RETRY_DELAY_MS = 500;
export const TRANSIENT_ERROR = 'transient failure';
export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as SQLite returns it. */
interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after_ms: number;
  created_at: string;
  updated_at: string;
}

/** The job JSON shape returned by every endpoint. */
export interface JobView {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const isIntegerIn = (v: unknown, min: number, max: number): v is number =>
  typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;

/** Validates a parsed request body, applying defaults. Returns every offending field. */
export function validateNewJob(body: unknown): ValidationResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }
  const { input, steps = DEFAULT_STEPS, failAttempts = DEFAULT_FAIL_ATTEMPTS } = body as Record<string, unknown>;
  if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'input must be a string of 1 to 1000 characters that is not only whitespace' });
  }
  if (!isIntegerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
  if (!isIntegerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
  if (fields.length > 0) return { ok: false, fields };
  // With no errors recorded, every value has passed its check above.
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

export function toJobView(r: JobRow): JobView {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function rowById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export type CreateResult = { kind: 'created' | 'replayed'; job: JobView } | { kind: 'conflict' };

/**
 * Creates a job, or, when `key` was already used, returns that job if the payload matches.
 * The check and the insert share one transaction, so a key never creates two jobs.
 */
export function createJob(db: DatabaseSync, value: NewJob, key: string | undefined): CreateResult {
  return transaction(db, (): CreateResult => {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === value.input && existing.steps === value.steps && existing.fail_attempts === value.failAttempts;
        return same ? { kind: 'replayed', job: toJobView(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after_ms, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, value.input, value.steps, value.failAttempts, key ?? null, now, now);
    return { kind: 'created', job: toJobView(rowById(db, id)!) };
  });
}

export function getJob(db: DatabaseSync, id: string): JobView | undefined {
  const row = rowById(db, id);
  return row ? toJobView(row) : undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): JobView[] {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  return rows.map(toJobView);
}

// ---- Worker operations ----

/** Puts jobs left `running` by a dead worker back in the queue. Returns how many were requeued. */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  const now = new Date().toISOString();
  return transaction(db, () => {
    const result = db
      .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after_ms = 0, updated_at = ? WHERE status = 'running'`)
      .run(now);
    return Number(result.changes);
  });
}

/** Claims the oldest queued job that is due, starting a new attempt. Returns undefined when none is due. */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobView | undefined {
  return transaction(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after_ms <= ? ORDER BY seq ASC LIMIT 1`)
      .get(nowMs) as unknown as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?`,
    ).run(new Date().toISOString(), next.id);
    return toJobView(rowById(db, next.id)!);
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, steps: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ).run(steps, output, new Date().toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(`UPDATE jobs SET status = 'failed', progress_completed = 0, error = ?, result_output = NULL, updated_at = ? WHERE id = ?`).run(
    error,
    new Date().toISOString(),
    id,
  );
}

/** Returns a job to the queue, not eligible again before `runAfterMs`. */
export function requeueJob(db: DatabaseSync, id: string, runAfterMs: number): void {
  db.prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after_ms = ?, updated_at = ? WHERE id = ?`).run(
    runAfterMs,
    new Date().toISOString(),
    id,
  );
}

// ---- Heartbeats ----

export function writeHeartbeat(db: DatabaseSync, name: string, atMs: number): void {
  db.prepare('INSERT INTO heartbeats (name, at_ms) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET at_ms = excluded.at_ms').run(name, atMs);
}

export function readHeartbeat(db: DatabaseSync, name: string): number | undefined {
  const row = db.prepare('SELECT at_ms FROM heartbeats WHERE name = ?').get(name) as unknown as { at_ms: number } | undefined;
  return row?.at_ms;
}

export function clearHeartbeat(db: DatabaseSync, name: string): void {
  db.prepare('DELETE FROM heartbeats WHERE name = ?').run(name);
}

